module ripple_carry_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);

    function automatic logic fa_carry(input logic x, input logic y, input logic z);
        fa_carry = (x & y) | (x & z) | (y & z);
    endfunction

    // Sum bit 0 is the XOR of the least-significant inputs and carry-in.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == (A[0] ^ B[0] ^ cin)
    );

    // Sum bit 1 uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == (A[1] ^ B[1] ^ fa_carry(A[0], B[0], cin))
    );

    // Sum bit 2 uses the carry propagated through bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == (A[2] ^ B[2] ^ fa_carry(A[1], B[1], fa_carry(A[0], B[0], cin)))
    );

    // Sum bit 3 uses the carry propagated through bits 0 to 2.
    check_sum_bit3: assert property (
        @(posedge clk) sum[3] == (A[3] ^ B[3] ^ fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], cin))))
    );

    // Carry-out is the final carry generated by the most-significant stage.
    check_cout: assert property (
        @(posedge clk) cout == fa_carry(A[3], B[3], fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], cin))))
    );

    // The concatenated outputs match a 5-bit addition of the inputs and carry-in.
    check_total_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, A} + {1'b0, B} + cin)
    );

endmodule